#!/usr/bin/env python3
"""Nolazco Labs Resource Planner — local Excel edition.
Python 3.10+; standard library only. The UI assets are embedded at the end.
Run: python3 Resource_Planner.py   |   Validate: --check   |   Help: --help
"""
from __future__ import annotations
import argparse
import base64
import datetime as dt
import hashlib
import io
import json
import math
import mimetypes
import os
from pathlib import Path
import posixpath
import secrets
import shutil
import sys
import tempfile
import threading
import webbrowser
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import unquote, urlsplit
from xml.dom import minidom
from zipfile import ZipFile, ZIP_DEFLATED

VERSION = '1.0.0'
DEFAULT_WORKBOOK = 'Resource_Planning_Database.xlsx'
NS = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'
REL = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'
DEPT_IDS = {'HW', 'SW', 'PM', 'PSE', 'FE', 'SS'}
HEADERS = {
    'Projects': ['project_id', 'name', 'code', 'customer', 'location', 'status'],
    'Resources': ['person_id', 'name', 'department_id', 'title', 'location'],
    'Allocations': ['allocation_id', 'project_id', 'department_id', 'start_month', 'end_month', 'allocation', 'person_id'],
    'Milestones': ['milestone_id', 'project_id', 'label', 'type', 'month'],
    'Departments': ['department_id', 'name', 'target'],
}

class DataError(Exception):
    """Invalid workbook or plan, with a user-actionable explanation."""

class ConflictError(DataError):
    pass


def parse_xml(raw):
    if b'<!DOCTYPE' in raw.upper() or b'<!ENTITY' in raw.upper():
        raise DataError('Unsupported XML content in workbook.')
    return minidom.parseString(raw)


def elements(node, local):
    return list(node.getElementsByTagNameNS('*', local))


def child_elements(node, local):
    return [c for c in node.childNodes if c.nodeType == c.ELEMENT_NODE and c.localName == local]


def text_of(node):
    return ''.join(c.data if c.nodeType in (c.TEXT_NODE, c.CDATA_SECTION_NODE) else text_of(c) for c in node.childNodes)


def new_element(doc, local):
    prefix = doc.documentElement.prefix
    return doc.createElementNS(NS, f'{prefix}:{local}' if prefix else local)


def resolve_part(base, target):
    path = posixpath.normpath(target.lstrip('/') if target.startswith('/') else posixpath.join(posixpath.dirname(base), target))
    if path.startswith('../'):
        raise DataError('Invalid workbook relationship path.')
    return path


def sheet_paths(parts):
    book = parse_xml(parts['xl/workbook.xml'])
    rels = parse_xml(parts['xl/_rels/workbook.xml.rels'])
    mapping = {r.getAttribute('Id'): resolve_part('xl/workbook.xml', r.getAttribute('Target')) for r in elements(rels, 'Relationship')}
    return {s.getAttribute('name'): mapping[s.getAttributeNS(REL, 'id')] for s in elements(book, 'sheet')}


def excel_epoch(parts):
    book = parse_xml(parts['xl/workbook.xml'])
    props = elements(book, 'workbookPr')
    return dt.datetime(1904, 1, 1) if props and props[0].getAttribute('date1904') in ('1','true') else dt.datetime(1899, 12, 30)


def read_parts(path):
    if not path.is_file():
        raise DataError(f'Workbook not found: {path.name}. Put it next to Resource_Planner.py or use --workbook.')
    if path.stat().st_size > 30_000_000:
        raise DataError('Workbook is larger than the 30 MB local database limit.')
    with ZipFile(path) as z:
        if sum(i.file_size for i in z.infolist()) > 100_000_000:
            raise DataError('Workbook uncompressed data exceeds the local database limit.')
        return {i.filename: z.read(i.filename) for i in z.infolist()}


def sheet_rows(parts, path, name):
    doc = parse_xml(parts[path]); shared = []
    if 'xl/sharedStrings.xml' in parts:
        shared = [''.join(text_of(t) for t in elements(si, 't')) for si in elements(parse_xml(parts['xl/sharedStrings.xml']), 'si')]
    cells = {}
    for row in elements(doc, 'row'):
        rid = int(row.getAttribute('r'))
        if rid < 4:
            continue
        result = {}
        for cell in child_elements(row, 'c'):
            address = cell.getAttribute('r')
            col = ''.join(ch for ch in address if ch.isalpha())
            if elements(cell, 'f'):
                raise DataError(f'{name}!{address}: formulas are not allowed in database tables. Enter a value.')
            kind = cell.getAttribute('t')
            vals = child_elements(cell, 'v')
            raw = text_of(vals[0]) if vals else ''
            if kind == 's':
                value = shared[int(raw)] if raw else ''
            elif kind == 'inlineStr':
                value = ''.join(text_of(t) for t in elements(cell, 't'))
            elif kind in ('str','d'):
                value = raw
            elif kind == 'e':
                raise DataError(f'{name}!{address} contains an Excel error.')
            elif raw:
                value = float(raw)
            else:
                value = ''
            result[col] = value
        cells[rid] = result
    headers = HEADERS[name]
    got = [cells.get(4, {}).get(chr(65+i),'') for i in range(len(headers))]
    if got != headers:
        raise DataError(f'{name}: keep the original column headers in row 4. Expected: {", ".join(headers)}.')
    allowed = {chr(65+i) for i in range(len(headers))}
    rows = []
    for rid in sorted(cells):
        if rid <= 4:
            continue
        values = cells[rid]
        if any(value not in ('',None) for key,value in values.items() if key not in allowed):
            raise DataError(f'{name} row {rid}: remove extra columns from this database table.')
        row = [values.get(chr(65+i),'') for i in range(len(headers))]
        if all(v in ('',None) for v in row):
            continue
        if not isinstance(row[0],str) or not row[0].strip():
            raise DataError(f'{name} row {rid}: the ID must be nonempty text, such as P5 or U15.')
        rows.append(row)
    if len(rows)>10000:
        raise DataError(f'{name} exceeds 10,000 rows.')
    return rows


def to_month(value, epoch, label):
    try:
        if isinstance(value,(int,float)) and not isinstance(value,bool) and math.isfinite(value):
            date = epoch + dt.timedelta(days=value)
        elif isinstance(value,str):
            date = dt.datetime.fromisoformat(value.replace('Z','+00:00'))
        else:
            raise ValueError()
        if date.day != 1:
            raise ValueError()
        index = (date.year-2026)*12+date.month-1
        if not 0<=index<=23:
            raise ValueError()
        return index
    except (ValueError,OverflowError):
        raise DataError(f'{label}: enter a real Excel date on the first day of a month between Jan 2026 and Dec 2027.') from None


def validate_plan(plan, depts):
    if not isinstance(plan,dict):
        raise DataError('Plan must be a JSON object.')
    if not isinstance(depts,list) or len(depts)!=6 or {d.get('id') for d in depts}!=DEPT_IDS:
        raise DataError('Departments must contain exactly HW, SW, PM, PSE, FE and SS.')
    def string(v, name, blank=False):
        if not isinstance(v,str) or (not blank and not v.strip()) or len(v)>1000 or any(ord(c)<32 and c not in '\t\n\r' for c in v):
            raise DataError(f'{name}: use valid text{", not blank" if not blank else ""}.')
    def number(v, name, upper):
        if isinstance(v,bool) or not isinstance(v,(int,float)) or not math.isfinite(v) or not 0<v<=upper:
            raise DataError(f'{name}: enter a percentage greater than 0% and no more than {upper*100:g}%.')
    def month(v):
        if type(v) is not int or not 0<=v<24:
            raise DataError('Plan months must be integers from 0 (Jan 2026) to 23 (Dec 2027).')
    for d in depts:
        string(d.get('name'),'Department name');number(d.get('target'),'Department target',1)
    for key in ('projects','people','bars','milestones'):
        rows=plan.get(key)
        if not isinstance(rows,list) or len(rows)>10000:
            raise DataError(f'{key} must be a list of at most 10,000 rows.')
        ids=set()
        for row in rows:
            if not isinstance(row,dict):
                raise DataError(f'Invalid row in {key}.')
            string(row.get('id'),f'{key} ID')
            if row['id'] in ids:
                raise DataError(f'Duplicate ID in {key}: {row["id"]}.')
            ids.add(row['id'])
    if not plan['projects']:
        raise DataError('Keep at least one project in the database.')
    projects={p['id'] for p in plan['projects']};people={p['id']:p for p in plan['people']}
    for p in plan['projects']:
        for k in ('name','code'):string(p.get(k),f'Project {k}')
        for k in ('customer','location'):string(p.get(k),f'Project {k}',True)
        if p.get('status') not in ('Active','Planning'):raise DataError('Project status must be Active or Planning.')
    for p in plan['people']:
        string(p.get('name'),'Resource name')
        for k in ('title','location'):string(p.get(k),f'Resource {k}',True)
        if p.get('dept') not in DEPT_IDS:raise DataError(f'Resource {p["id"]} has an invalid department.')
    for b in plan['bars']:
        if b.get('project') not in projects:raise DataError(f'Allocation {b["id"]} references an unknown project.')
        if b.get('dept') not in DEPT_IDS:raise DataError(f'Allocation {b["id"]} has an invalid department.')
        month(b.get('start'));month(b.get('end'))
        if b['end']<b['start']:raise DataError(f'Allocation {b["id"]}: end month precedes start month.')
        number(b.get('allocation'),f'Allocation {b["id"]}',20)
        pid=b.get('personId')
        if pid and (pid not in people or people[pid]['dept']!=b['dept']):
            raise DataError(f'Allocation {b["id"]}: person must exist and belong to {b["dept"]}.')
    for m in plan['milestones']:
        if m.get('project') not in projects:raise DataError(f'Milestone {m["id"]} references an unknown project.')
        string(m.get('label'),'Milestone label');month(m.get('month'))
        if m.get('type') not in ('internal','external'):raise DataError('Milestone type must be internal or external.')


def plan_from_parts(parts):
    paths=sheet_paths(parts)
    missing=set(HEADERS)-set(paths)
    if missing:raise DataError('Missing worksheet(s): '+', '.join(sorted(missing)))
    rows={name:sheet_rows(parts,paths[name],name) for name in HEADERS}
    epoch=excel_epoch(parts)
    depts=[dict(id=r[0],name=r[1],target=r[2]) for r in rows['Departments']]
    plan={
        'projects':[dict(zip(('id','name','code','customer','location','status'),r)) for r in rows['Projects']],
        'people':[dict(zip(('id','name','dept','title','location'),r)) for r in rows['Resources']],
        'bars':[],
        'milestones':[],
    }
    for r in rows['Allocations']:
        b=dict(id=r[0],project=r[1],dept=r[2],start=to_month(r[3],epoch,f'Allocation {r[0]} start'),end=to_month(r[4],epoch,f'Allocation {r[0]} end'),allocation=r[5])
        if r[6]:b['personId']=r[6]
        plan['bars'].append(b)
    for r in rows['Milestones']:
        plan['milestones'].append(dict(id=r[0],project=r[1],label=r[2],type=r[3],month=to_month(r[4],epoch,f'Milestone {r[0]}')))
    validate_plan(plan,depts)
    return plan,depts


def read_workbook(path):
    return plan_from_parts(read_parts(Path(path)))


def revision_of(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def rows_for_plan(plan,epoch):
    def serial(month):return (dt.datetime(2026+month//12,1+month%12,1)-epoch).days
    return {
        'Projects':[[p[k] for k in ('id','name','code','customer','location','status')] for p in plan['projects']],
        'Resources':[[p[k] for k in ('id','name','dept','title','location')] for p in plan['people']],
        'Allocations':[[b['id'],b['project'],b['dept'],serial(b['start']),serial(b['end']),b['allocation'],b.get('personId','')] for b in plan['bars']],
        'Milestones':[[m['id'],m['project'],m['label'],m['type'],serial(m['month'])] for m in plan['milestones']],
    }


def write_sheet(parts,path,name,rows):
    doc=parse_xml(parts[path]);sheet=doc.documentElement
    data=elements(doc,'sheetData')[0];old_rows=child_elements(data,'row')
    template=next((r for r in old_rows if r.getAttribute('r')=='5'),None)
    style={}
    if template:
        for c in child_elements(template,'c'):
            style[''.join(x for x in c.getAttribute('r') if x.isalpha())]=c.getAttribute('s')
    for row in old_rows:
        if int(row.getAttribute('r'))>=5:data.removeChild(row)
    actual_rows=rows or [['']*len(HEADERS[name])]
    for i,values in enumerate(actual_rows,5):
        row=new_element(doc,'row');row.setAttribute('r',str(i));row.setAttribute('ht','25');row.setAttribute('customHeight','1')
        for j,value in enumerate(values):
            col=chr(65+j);c=new_element(doc,'c');c.setAttribute('r',f'{col}{i}')
            if style.get(col):c.setAttribute('s',style[col])
            if isinstance(value,(int,float)):
                c.setAttribute('t','n');v=new_element(doc,'v');v.appendChild(doc.createTextNode(str(value)));c.appendChild(v)
            elif value not in ('',None):
                c.setAttribute('t','inlineStr');inline=new_element(doc,'is');t=new_element(doc,'t');t.setAttribute('xml:space','preserve');t.appendChild(doc.createTextNode(str(value)));inline.appendChild(t);c.appendChild(inline)
            row.appendChild(c)
        data.appendChild(row)
    last=max(5,4+len(rows));last_col=chr(64+len(HEADERS[name]));ref=f'A4:{last_col}{last}'
    dims=elements(doc,'dimension')
    if dims:dims[0].setAttribute('ref',f'A1:{last_col}{last}')
    for f in elements(doc,'autoFilter'):f.setAttribute('ref',ref)
    parts[path]=doc.toxml(encoding='utf-8')
    relpath=posixpath.join(posixpath.dirname(path),'_rels',posixpath.basename(path)+'.rels')
    if relpath in parts:
        rels=parse_xml(parts[relpath])
        for rel in elements(rels,'Relationship'):
            if rel.getAttribute('Type').endswith('/table'):
                tpath=resolve_part(path,rel.getAttribute('Target'));tdoc=parse_xml(parts[tpath]);tdoc.documentElement.setAttribute('ref',ref)
                for f in elements(tdoc,'autoFilter'):f.setAttribute('ref',ref)
                parts[tpath]=tdoc.toxml(encoding='utf-8')


def write_workbook(path,plan,expected_revision):
    path=Path(path)
    if path.with_name('~$'+path.name).exists():
        raise ConflictError('Excel has this workbook open. Close Excel, then click Retry save.')
    before=path.read_bytes()
    if hashlib.sha256(before).hexdigest()!=expected_revision:
        raise ConflictError('The workbook changed outside this tab. Export your unsaved plan, then use Reload Excel before making further changes.')
    parts=read_parts(path);_,depts=plan_from_parts(parts);validate_plan(plan,depts)
    paths=sheet_paths(parts)
    for name,rows in rows_for_plan(plan,excel_epoch(parts)).items():write_sheet(parts,paths[name],name,rows)
    # Validate serialized cells before replacing the user's database.
    roundtrip,_=plan_from_parts(parts)
    keys=('projects','people','bars','milestones')
    # Optional blank personId is canonicalized out; otherwise compare all modeled fields.
    canonical=json.loads(json.dumps(plan))
    for b in canonical['bars']:
        if not b.get('personId'):b.pop('personId',None)
    if any(roundtrip[k]!=canonical[k] for k in keys):raise DataError('Workbook verification failed; the original file was preserved.')
    backupdir=path.parent/'backups';backupdir.mkdir(exist_ok=True)
    stamp=dt.datetime.now().strftime('%Y%m%d_%H%M%S_%f')
    backup=backupdir/f'{path.stem}_{stamp}.xlsx'
    with backup.open('xb') as f:f.write(before)
    handle,tmp=tempfile.mkstemp(prefix='.resource-planner-',suffix='.xlsx',dir=path.parent);os.close(handle)
    try:
        with ZipFile(tmp,'w',ZIP_DEFLATED) as z:
            for name,raw in parts.items():z.writestr(name,raw)
        if revision_of(path)!=expected_revision:
            raise ConflictError('Excel changed while saving. The original file was preserved; export your plan, then reload.')
        os.replace(tmp,path)
    except PermissionError:
        raise ConflictError('Cannot replace the workbook. Close Excel and check folder permissions, then click Retry save.') from None
    finally:
        if os.path.exists(tmp):os.unlink(tmp)
    return revision_of(path)


class WorkbookLock:
    """OS advisory lock avoids multiple launcher processes writing one workbook."""
    def __init__(self,path):self.path=Path(str(path)+'.app.lock');self.file=None
    def __enter__(self):
        self.file=self.path.open('a+b');self.file.seek(0);self.file.write(b'0');self.file.flush();self.file.seek(0)
        try:
            if os.name=='nt':
                import msvcrt
                msvcrt.locking(self.file.fileno(),msvcrt.LK_NBLCK,1)
            else:
                import fcntl
                fcntl.flock(self.file,fcntl.LOCK_EX|fcntl.LOCK_NB)
        except OSError:
            self.file.close();self.file=None
            raise DataError('This workbook is already open in another Resource Planner process. Use that window or stop it first.') from None
        return self
    def __exit__(self,*_):
        if self.file:self.file.close()


class PlannerServer(ThreadingHTTPServer):
    daemon_threads=True
    def __init__(self,address,workbook,assets):
        super().__init__(address,Handler)
        self.workbook=Path(workbook);self.assets=assets;self.token=secrets.token_urlsafe(32);self.write_lock=threading.Lock()
        self.expected_host=f'127.0.0.1:{self.server_port}'


class Handler(BaseHTTPRequestHandler):
    server_version='ResourcePlanner/'+VERSION
    def log_message(self,format,*args):
        # Log status only; never log plan contents or session tokens.
        print(f'[{self.log_date_time_string()}] {format % args}')
    def send_bytes(self,status,body,content_type):
        self.send_response(status);self.send_header('Content-Type',content_type);self.send_header('Content-Length',str(len(body)));self.send_header('Cache-Control','no-store');self.send_header('X-Content-Type-Options','nosniff');self.send_header('X-Frame-Options','DENY');self.send_header('Referrer-Policy','no-referrer');self.end_headers()
        if self.command!='HEAD':self.wfile.write(body)
    def send_json(self,status,payload):self.send_bytes(status,json.dumps(payload,allow_nan=False).encode(), 'application/json; charset=utf-8')
    def valid_host(self):
        if self.headers.get('Host')!=self.server.expected_host:
            self.send_json(403,{'error':'Open the exact 127.0.0.1 address printed by the launcher.'});return False
        origin=self.headers.get('Origin')
        if origin and origin!='http://'+self.server.expected_host:
            self.send_json(403,{'error':'Requests from other websites are not allowed.'});return False
        if self.headers.get('Sec-Fetch-Site')=='cross-site':
            self.send_json(403,{'error':'Cross-site requests are not allowed.'});return False
        return True
    def do_GET(self):
        if not self.valid_host():return
        path=unquote(urlsplit(self.path).path)
        if path=='/api/plan':
            try:
                with self.server.write_lock:
                    before=revision_of(self.server.workbook);plan,depts=read_workbook(self.server.workbook)
                    if revision_of(self.server.workbook)!=before:raise ConflictError('Workbook changed while loading. Close Excel, then retry.')
                self.send_json(200,{'plan':plan,'departments':depts,'revision':before,'token':self.server.token})
            except (DataError,OSError,ValueError,KeyError) as e:self.send_json(409,{'error':str(e)})
            return
        name='index.html' if path=='/' else path.lstrip('/')
        raw=self.server.assets.get(name)
        if raw is None:self.send_json(404,{'error':'File not found.'});return
        mime=mimetypes.guess_type(name)[0] or 'application/octet-stream'
        if name.endswith('.js'):mime='application/javascript'
        self.send_bytes(200,raw,mime)
    def do_HEAD(self):self.do_GET()
    def do_PUT(self):
        if not self.valid_host():return
        if urlsplit(self.path).path!='/api/plan':self.send_json(404,{'error':'Unknown endpoint.'});return
        if not secrets.compare_digest(self.headers.get('X-Local-Token',''),self.server.token):self.send_json(403,{'error':'Session expired. Export unsaved changes, then reload the app.'});return
        if not self.headers.get('Content-Type','').startswith('application/json'):self.send_json(415,{'error':'JSON content is required.'});return
        try:
            length=int(self.headers.get('Content-Length','0'))
            if not 0<length<=5_000_000:raise DataError('Save request must be between 1 byte and 5 MB.')
            payload=json.loads(self.rfile.read(length))
            if not isinstance(payload,dict) or not isinstance(payload.get('revision'),str):raise DataError('Missing workbook revision.')
            with self.server.write_lock:
                revision=write_workbook(self.server.workbook,payload.get('plan'),payload['revision'])
            self.send_json(200,{'revision':revision})
        except ConflictError as e:self.send_json(409,{'error':str(e)})
        except (DataError,ValueError,TypeError,KeyError) as e:self.send_json(400,{'error':str(e)})
        except OSError as e:self.send_json(500,{'error':f'Save failed: {e}. Export your plan before closing.'})


def unpack_assets():
    with ZipFile(io.BytesIO(base64.b64decode(EMBEDDED_ASSETS))) as z:
        return {name:z.read(name) for name in z.namelist() if not name.endswith('/')}


def main(argv=None):
    parser=argparse.ArgumentParser(description='Run Resource Planner locally with its Excel database. No pip packages required.')
    parser.add_argument('--workbook',type=Path,default=Path(sys.executable if getattr(sys, 'frozen', False) else __file__).resolve().with_name(DEFAULT_WORKBOOK),help='Path to the Excel database')
    parser.add_argument('--port',type=int,default=8765,help='Local port (default 8765; use 0 for an available port)')
    parser.add_argument('--no-browser',action='store_true',help='Do not open the browser automatically')
    parser.add_argument('--check',action='store_true',help='Validate the database and exit without changing it')
    args=parser.parse_args(argv)
    if sys.version_info<(3,10):parser.error('Python 3.10 or newer is required.')
    if not 0<=args.port<=65535:parser.error('Port must be between 0 and 65535.')
    workbook=args.workbook.expanduser().resolve()
    try:
        plan,_=read_workbook(workbook)
        if args.check:
            print(f'Workbook valid: {len(plan["projects"])} projects, {len(plan["people"])} resources, {len(plan["bars"])} allocations, {len(plan["milestones"])} milestones.');return 0
        with WorkbookLock(workbook):
            server=PlannerServer(('127.0.0.1',args.port),workbook,unpack_assets())
            url=f'http://127.0.0.1:{server.server_port}'
            print(f'\nNolazco Labs Resource Planner {VERSION}\n{url}\n\nDatabase: {workbook}\nKeep this window open. Close Excel while planning.\nWait for Saved to Excel before closing the app.\nPress Ctrl+C here to stop.\n',flush=True)
            if not args.no_browser:threading.Timer(.7,lambda:webbrowser.open(url)).start()
            try:server.serve_forever()
            except KeyboardInterrupt:print('\nPlanner stopped. Your saved workbook remains in place.')
            finally:server.server_close()
        return 0
    except Exception as e:
        print(f'\nCannot start Resource Planner: {e}\nCheck the workbook path, close Excel, and try again.\nIf the port is busy, use --port 8766.',file=sys.stderr)
        return 1


EMBEDDED_ASSETS = ''
if __name__=='__main__':
    result = main()
    if result and getattr(sys, 'frozen', False) and len(sys.argv) == 1:
        input('Press Enter to close...')
    raise SystemExit(result)
